class TimeExtension(Extension):
    """Extension for adding time/date functionality in templates.

    Provides a `now` tag that works similarly to jinja2-time's implementation.
    """

    tags = {'now'}

    def _get_timezone(self, tz: str) -> datetime.timezone | None:
        """Get timezone object from string."""
        if tz == 'utc':
            return datetime.timezone.utc
        elif tz == 'local':
            return None
        raise ValueError(f"Unknown timezone: {tz}")

    def parse(self, parser: Parser) -> nodes.Output:
        """Parse the now tag."""
        lineno = next(parser.stream).lineno  # Get 'now' token lineno

        # Parse arguments
        args = [parser.parse_expression()]  # First arg is required (timezone)
        if parser.stream.skip_if('comma'):
            args.append(parser.parse_expression())  # Optional format string
        else:
            args.append(nodes.Const('%Y-%m-%d'))  # Default format

        # Create call to _render_now with the arguments
        return nodes.Output([
            self.call_method('_render_now', args)
        ]).set_lineno(lineno)

    def _render_now(self, timezone_str: str, fmt: str = '%Y-%m-%d') -> str:
        """Render current time in given timezone and format."""
        tz = self._get_timezone(timezone_str)
        now = datetime.datetime.now(tz=tz)
        return now.strftime(fmt)"}

